}
def translate(s):
    return "".join(codon_table[k] for k in [s[i:i+3] for i in range(0, len(s)-2, 3)])

def revcomp(s):
    return s.translate(str.maketrans("ACGT", "TGCA"))[::-1]

def frame_scores(seq):
    res = []
    for f in range(3):
        for strand, s in [("+", seq), ("-", revcomp(seq))]:
            prot = translate(s[f:] if strand=="+" else s[f:])
            stops = prot.count("*")
            length = len(prot)
            res.append((strand, f+1, stops, length, -stops/length))
    return res

