}
def codon_count(region):
    d = {}
    for i in range(0,len(region)-2,3):
        d[region[i:i+3]] = d.get(region[i:i+3],0)+1
    return d
obs = codon_count(region)
fourfour = {aa: [c for c in cs if len(cs)==4] for aa,cs in fam.items() if len(cs)==4}
# count codons ending in G/C vs A/T within each 4-fold family
gc_end = 0; at_end = 0
for aa, cs in fourfour.items():
    for c in cs:
        if c[2] in "GC": gc_end += obs.get(c,0)
        else: at_end += obs.get(c,0)
print("4-fold family GC-ending codons:", gc_end, "AT-ending:", at_end, "fraction GC3:", gc_end/(gc_end+at_end))

def randomize_dinuc(seq):
    pairs = [seq[2*i:2*i+2] for i in range(len(seq)//2)]
    random.shuffle(pairs)
    return "".join(pairs)
random.seed(1)
