for _ in range(200):
    r = randomize_dinuc(region)
    d = codon_count(r)
    g = a = 0
    for aa, cs in fourfour.items():
        for c in cs:
            if c[2] in "GC": g += d.get(c,0)
            else: a += d.get(c,0)
    vals.append(g/(g+a))
print("dinuc-shuffle null: mean %.3f, sd %.3f" % (statistics.mean(vals), statistics.pstdev(vals)))
